+	t.is(subprocess.stdio[3], null);
+
+	const {stdio} = await subprocess;
+	t.is(stdio.length, 4);
+	t.is(stdio[3], undefined);
+};
+
+test('stdio[*] undefined means "ignore"', testFd3Undefined, undefined, {});
